 33	/* * * * * * * * * * * * * * * * * * * * * * * 
 34	Memory Layout
 35	0x5000_0000 ~ 0x5020_0000       BBL
 36	0x5020_0000 ~ 0x5040_0000       Boot
 37	0x5040_0000 ~ 0x5140_0000       Kernel
 38	0x5140_0000 ~ 0x5140_2000       Kernel Stack
 39	0x5140_2000 ~ 0x5200_0000       Kernel Mem
 40	0x5200_0000 ~ 0x5e00_0000       User Mem
 41	0x5e00_0000 ~ 0x6000_0000       Page Table
 42	* * * * * * * * * * * * * * * * * * * * * * */
 43	
 44	#define PAGE_SIZE 4096
 45	#define INIT_KERNEL_STACK   0xffffffc051400000lu    //kva
 46	#define USER_STACK_ADDR     0xf00010000lu           //va
 47	
 48	#define KERNEL_MEM_BEGIN    0x51402000lu            //pa
 49	#define KERNEL_MEM_END      0x52000000lu            //pa
 50	#define USER_MEM_BEGIN      0x52000000lu            //pa
 51	#define USER_MEM_END        0x5e000000lu            //pa
 52	#define MEM_END             0x60000000lu            //pa
 53	
 54	#define SWAP_BEGIN 2048
 55	
 56	/* Rounding: only works for n = power of two */
 57	#define ROUND(a, n)     (((((uint64_t)(a))+(n)-1)) & ~((n)-1))
 58	#define ROUNDDOWN(a, n) (((uint64_t)(a)) & ~((n)-1))
 59	
 60	extern ptr_t kernel_memCurr;
 61	extern ptr_t user_memCurr;
 62	
 63	#define FREE_PGDIR_ADDR (PGDIR_PA + 3 * PAGE_SIZE)
 64	#define PGDIR_PAGE_NUM ((MEM_END - FREE_PGDIR_ADDR) / PAGE_SIZE)
 65	typedef struct pgdir_page{
 66	    uint8_t valid;
 67	}pgdir_page_t;
 68	extern pgdir_page_t pgdir_page[PGDIR_PAGE_NUM];
