 70	#define USER_MEM_SIZE (USER_MEM_END - USER_MEM_BEGIN)
 71	#define USER_PAGE_NUM (USER_MEM_SIZE / PAGE_SIZE)
 72	typedef struct user_page{
 73	    uint8_t valid;
 74	    uint8_t pin;
 75	    PTE* pgtable;
 76	}user_page_t;
 77	extern user_page_t user_page[USER_PAGE_NUM];
