 40	int pa2num(uintptr_t pa)
 41	{
 42	    return (pa - USER_MEM_BEGIN) / PAGE_SIZE;
 43	}
 44	ptr_t num2pa(int num)
 45	{
 46	    return (USER_MEM_BEGIN + num * PAGE_SIZE);
 47	}
