 85	// returns pa
 86	void *kmalloc(size_t size)
 87	{
 88	    // align 4
 89	    ptr_t ret = ROUND(kernel_memCurr, 4);
 90	    kernel_memCurr = ret + size;
 91	    return (void*)ret;
 92	}
