 94	// select a user page to write to disk (NRU), returns pa
 95	ptr_t selete_page()
 96	{
 97	    /* Not Recently Used with a second chance: sweep the frames, give every
 98	     * page whose accessed bit is set one more round (clearing the bit as we
 99	     * pass by), and evict the first one that survived a whole sweep unused.
100	     * Pinned frames (kernel stacks, shared pages) and frames that are not
101	     * reachable through a page table entry can never be evicted. */
102	    static int clock_hand = 0;
103	
104	    for(int step = 0; step < 2 * USER_PAGE_NUM; step++){
105	        int i = clock_hand;
106	        clock_hand = (clock_hand + 1) % USER_PAGE_NUM;
107	
108	        if(!user_page[i].valid || user_page[i].pin || user_page[i].pgtable == NULL){
109	            continue;
110	        }
111	        if(get_attribute(*user_page[i].pgtable, _PAGE_ACCESSED)){
112	            clear_attribute(user_page[i].pgtable, _PAGE_ACCESSED);
113	            continue;
114	        }
115	        return num2pa(i);
116	    }
117	
118	    /* every single frame is pinned, there is nothing we can do */
119	    assert(0);
120	    return 0;
121	}
122	
123	void write_to_sd(ptr_t pa)
124	{
125	    int i;
126	    for(i = 0; i < DISK_PAGE_NUM; i++){
127	        if(disk_page[i].valid == 0){
128	            break;
129	        }
130	    }
131	    assert(i != DISK_PAGE_NUM);
132	    disk_page[i].valid = 1;
133	
134	    sbi_sd_write((unsigned int)pa, PAGE_SD_BLOCKS, SWAP_BEGIN + i * PAGE_SD_BLOCKS);
135	
136	    /* Remember where the page went inside its own page table entry: the
137	     * frame number field now holds the swap slot and _PAGE_SOFT marks the
138	     * entry as "on disk" so that the page fault handler can tell it apart
139	     * from a never-mapped address. */
140	    PTE *pgtable = user_page[pa2num(pa)].pgtable;
141	    if(pgtable != NULL){
142	        clear_attribute(pgtable, _PAGE_PRESENT);
143	        set_attribute(pgtable, _PAGE_SOFT);
144	        set_pfn(pgtable, (uint64_t)i);
145	    }
146	
147	    flush_tlb_all();
148	    free_user_page(pa);
149	}
