151	unsigned long free_page_num()
152	{
153	    unsigned long ret = 0;
154	    for(int i = 0; i < USER_PAGE_NUM; i++){
155	        if(user_page[i].valid == 0){
156	            ret++;
157	        }
158	    }
159	    return ret;
160	}
