162	/* Walk the three levels of `pgdir` (a pa) down to the leaf entry for `va`,
163	 * creating the intermediate tables on the way. Returns a pointer to the leaf
164	 * PTE, which the caller reaches through the kernel's direct mapping. */
165	static PTE* walk_pgdir(uintptr_t va, uintptr_t pgdir)
166	{
167	    uint64_t vpn[3];
168	    vpn[2] = (va >> VPN2_SHIFT) & VPN_MASK;
169	    vpn[1] = (va >> VPN1_SHIFT) & VPN_MASK;
170	    vpn[0] = (va >> VPN0_SHIFT) & VPN_MASK;
171	
172	    PTE *table = (PTE*)pa2kva(pgdir);
173	    for(int level = 2; level > 0; level--){
174	        PTE *entry = table + vpn[level];
175	        if(!get_attribute(*entry, _PAGE_PRESENT)){
176	            PTE *next = alloc_pgdir_page();
177	            *entry = 0;
178	            set_pfn(entry, (uintptr_t)next >> NORMAL_PAGE_SHIFT);
179	            /* a pointer entry carries no R/W/X bits */
180	            set_attribute(entry, _PAGE_PRESENT);
181	        }
182	        table = (PTE*)pa2kva(get_pa(*entry));
183	    }
184	    return table + vpn[0];
185	}
186	
187	/* Same walk, but without creating anything: returns NULL when the address is
188	 * not backed by a leaf entry at all. */
189	PTE* find_pte(uintptr_t va, uintptr_t pgdir)
190	{
191	    uint64_t vpn[3];
192	    vpn[2] = (va >> VPN2_SHIFT) & VPN_MASK;
193	    vpn[1] = (va >> VPN1_SHIFT) & VPN_MASK;
194	    vpn[0] = (va >> VPN0_SHIFT) & VPN_MASK;
195	
196	    PTE *table = (PTE*)pa2kva(pgdir);
197	    for(int level = 2; level > 0; level--){
198	        PTE *entry = table + vpn[level];
199	        if(!get_attribute(*entry, _PAGE_PRESENT)){
200	            return NULL;
201	        }
202	        table = (PTE*)pa2kva(get_pa(*entry));
203	    }
204	    return table + vpn[0];
205	}
206	
207	/*
208	 * Make sure `va` is backed by a physical frame in `pgdir` (a pa) and return
209	 * the kernel virtual address of that frame.  A page that had been swapped out
210	 * is read back from the SD card first.  The signature matches the callback
211	 * load_elf() expects, so it doubles as the "prepare page" hook of do_exec().
212	 */
213	uintptr_t alloc_page_helper(uintptr_t va, uintptr_t pgdir)
214	{
215	    va = ROUNDDOWN(va, PAGE_SIZE);
216	    PTE *pte = walk_pgdir(va, pgdir);
217	
218	    if(!get_attribute(*pte, _PAGE_PRESENT)){
219	        if(get_attribute(*pte, _PAGE_SOFT)){
220	            /* the page lives in the swap area, fetch it back */
221	            uint64_t slot = get_pfn(*pte);
222	            uintptr_t pa = alloc_user_page(0, pte);
223	            sbi_sd_read((unsigned int)pa, PAGE_SD_BLOCKS, SWAP_BEGIN + slot * PAGE_SD_BLOCKS);
224	            disk_page[slot].valid = 0;
225	            *pte = 0;
226	            set_pfn(pte, pa >> NORMAL_PAGE_SHIFT);
227	        }
228	        else{
229	            uintptr_t pa = alloc_user_page(0, pte);
230	            *pte = 0;
231	            set_pfn(pte, pa >> NORMAL_PAGE_SHIFT);
232	        }
233	        set_attribute(pte, _PAGE_PRESENT | _PAGE_READ | _PAGE_WRITE | _PAGE_EXEC |
234	                           _PAGE_USER | _PAGE_ACCESSED | _PAGE_DIRTY);
235	        flush_tlb_all();
236	    }
237	
238	    return pa2kva(get_pa(*pte));
239	}
240	
241	/*
242	 * Virtual Memory Layout
243	 * 0x0_0000_1000 ~ 0x0_0001_0000: share
244	 * 0x0_0001_0000 ~ 0x0_0001_3000: code
245	 * 0xf_0000_f000 ~ 0xf_0001_0000: stack
246	 */
247	PTE* init_page_table()
248	{
249	    PTE *pgdir = alloc_pgdir_page();
250	    PTE *pgdir_kva = (PTE*)pa2kva((uintptr_t)pgdir);
251	    PTE *kernel_pgdir_kva = (PTE*)pa2kva(PGDIR_PA);
252	
253	    /* Every address space keeps the kernel mapped: VPN2 of the kernel window
254	     * 0xffffffc0_00000000 is 0x101 and boot.c installed it there. */
255	    pgdir_kva[0x101] = kernel_pgdir_kva[0x101];
256	
257	    /* init_pcb() resolves addresses with get_kva_of(), which only walks the
258	     * table, so the whole code region has to be mapped up front. */
259	    for(uintptr_t va = USER_CODE_BEGIN; va < USER_CODE_END; va += PAGE_SIZE){
260	        alloc_page_helper(va, (uintptr_t)pgdir);
261	    }
262	    /* and one page of user stack to start on */
263	    alloc_page_helper(USER_STACK_ADDR - PAGE_SIZE, (uintptr_t)pgdir);
264	
265	    return pgdir;
266	}
267	
268	void free_process_user_page(PTE* pgdir)
269	{
270	    if(pgdir == NULL || (uintptr_t)pgdir == PGDIR_PA){
271	        return;
272	    }
273	
274	    PTE *pgdir_kva = (PTE*)pa2kva((uintptr_t)pgdir);
275	
276	    /* Only the user half is owned by this process; VPN2 >= 0x100 belongs to
277	     * the kernel window, which is shared by everybody. */
278	    for(int vpn2 = 0; vpn2 < NUM_PTE_ENTRY / 2; vpn2++){
279	        if(!get_attribute(pgdir_kva[vpn2], _PAGE_PRESENT)){
280	            continue;
281	        }
282	        uintptr_t second_pa = get_pa(pgdir_kva[vpn2]);
283	        PTE *second_kva = (PTE*)pa2kva(second_pa);
284	
285	        for(int vpn1 = 0; vpn1 < NUM_PTE_ENTRY; vpn1++){
286	            if(!get_attribute(second_kva[vpn1], _PAGE_PRESENT)){
287	                continue;
288	            }
289	            uintptr_t third_pa = get_pa(second_kva[vpn1]);
290	            PTE *third_kva = (PTE*)pa2kva(third_pa);
291	
292	            for(int vpn0 = 0; vpn0 < NUM_PTE_ENTRY; vpn0++){
293	                PTE leaf = third_kva[vpn0];
294	                if(leaf == 0){
295	                    continue;
296	                }
297	                if(get_attribute(leaf, _PAGE_PRESENT)){
298	                    uintptr_t pa = get_pa(leaf);
299	                    int shared = 0;
300	                    /* a shared page only goes away with its last user */
301	                    for(int k = 0; k < SHM_PAGE_NUM; k++){
302	                        if(shm_page[k].count > 0 && shm_page[k].pa == pa){
303	                            shm_page[k].count--;
304	                            if(shm_page[k].count == 0){
305	                                free_user_page(pa);
306	                                shm_page[k].pa = 0;
307	                            }
308	                            shared = 1;
309	                            break;
310	                        }
311	                    }
312	                    if(!shared){
313	                        free_user_page(pa);
314	                    }
315	                }
316	                else if(get_attribute(leaf, _PAGE_SOFT)){
317	                    /* the page was swapped out, give the disk slot back */
318	                    disk_page[get_pfn(leaf)].valid = 0;
319	                }
320	                third_kva[vpn0] = 0;
321	            }
322	
323	            free_pgdir_page(third_pa);
324	            second_kva[vpn1] = 0;
325	        }
326	
327	        free_pgdir_page(second_pa);
328	        pgdir_kva[vpn2] = 0;
329	    }
330	
331	    free_pgdir_page((uintptr_t)pgdir);
332	    flush_tlb_all();
333	}
