393	void handle_page_fault(regs_context_t *regs, uint64_t stval, uint64_t cause)
394	{
395	    /* Anything outside the user half of the Sv39 address space is a genuine
396	     * kernel bug; let the generic handler dump the context. */
397	    if(stval >= (1lu << (VPN2_SHIFT + PPN_BITS - 1))){
398	        handle_other(regs, stval, cause);
399	        return;
400	    }
401	
402	    /* demand paging: give the faulting address a frame (or fetch it back
403	     * from the swap area) and let the instruction run again */
404	    alloc_page_helper(stval, (uintptr_t)current_running[cpu_id]->pgdir);
405	}

