     9	void *ioremap(unsigned long phys_addr, unsigned long size)
    10	{
    11	    // map phys_addr to a virtual address
    12	    // then return the virtual address
    13	    uintptr_t ret = io_base;
    14	    while(size > 0){
    15	        int VPN2 = (io_base >> VPN2_SHIFT) & VPN_MASK;
    16	        int VPN1 = (io_base >> VPN1_SHIFT) & VPN_MASK;
    17	        int VPN0 = (io_base >> VPN0_SHIFT) & VPN_MASK;
    18	
    19	        if(!get_attribute(*(pgdir + VPN2), _PAGE_PRESENT)){
    20	            PTE *second_level_pgdir = (PTE*)(PGDIR_PA + 2 * NORMAL_PAGE_SIZE);
    21	            set_pfn(pgdir + VPN2, (uint64_t)second_level_pgdir >> NORMAL_PAGE_SHIFT);
    22	            set_attribute(pgdir + VPN2, _PAGE_PRESENT);
    23	        }
    24	
    25	        PTE* second_level_pgdir = (PTE*)get_pa(*(pgdir + VPN2));
    26	        second_level_pgdir = (PTE*)pa2kva((uintptr_t)second_level_pgdir);
    27	        if(!get_attribute(*(second_level_pgdir + VPN1), _PAGE_PRESENT)){
    28	            PTE *last_level_pgdir = alloc_pgdir_page();
    29	            set_pfn(second_level_pgdir + VPN1, (uint64_t)last_level_pgdir >> NORMAL_PAGE_SHIFT);
    30	            set_attribute(second_level_pgdir + VPN1, _PAGE_PRESENT);
    31	        }
    32	
    33	        PTE* last_level_pgdir = (PTE*)get_pa(*(second_level_pgdir + VPN1));
    34	        last_level_pgdir = (PTE*)pa2kva((uintptr_t)last_level_pgdir);
    35	        if(!get_attribute(*(last_level_pgdir + VPN0), _PAGE_PRESENT)){
    36	            set_pfn(last_level_pgdir + VPN0, phys_addr >> NORMAL_PAGE_SHIFT);
    37	            set_attribute(last_level_pgdir + VPN0, _PAGE_PRESENT);
    38	            set_attribute(last_level_pgdir + VPN0, _PAGE_ACCESSED);
    39	            set_attribute(last_level_pgdir + VPN0, _PAGE_DIRTY);
    40	            set_attribute(last_level_pgdir + VPN0, _PAGE_EXEC);
    41	            set_attribute(last_level_pgdir + VPN0, _PAGE_WRITE);
    42	            set_attribute(last_level_pgdir + VPN0, _PAGE_READ);
    43	        }
    44	
    45	        size -= NORMAL_PAGE_SIZE;
    46	        phys_addr += NORMAL_PAGE_SIZE;
    47	        io_base += NORMAL_PAGE_SIZE;
    48	    }
    49	    local_flush_tlb_all();
    50	    return (void *)ret;
    51	}
